nto": "Montaria Especial", "tipo_progressao": "faixa_nivel_estatico", "regra_calculo": "Os valores de PV, IP, FR e INT sobrescrevem os modificadores anteriores com base no nivel atual do personagem. Os especiais sao cumulativos.", "niveis": {"1-3": {"pv_bonus": 2, "ip_bonus": 0, "fr_bonus": 1, "int_bonus": 0, "especiais": ["Partilhar Magias", "Partilhar Resistencia"]}, "4-6": {"pv_bonus": 5, "ip_bonus": 1, "fr_bonus": 2, "int_bonus": 1, "especiais": ["Partilhar Magias", "Partilhar Resistencia"]}, "7-10": {"pv_bonus": 7, "ip_bonus": 1, "fr_bonus": 3, "int_bonus": 2, "especiais": ["Partilhar Magias", "Partilhar Resistencia"]}, "11+": {"pv_bonus": 10, "ip_bonus": 2, "fr_bonus": 4, "int_bonus": 3, "especiais": ["Partilhar Magias", "Partilhar Resistencia", "Protecao a Magia 1d6"]}}}, "niveis_familiar": {"aprimoramento": "Familiares", "tipo_progressao": "faixa_nivel_estatico", "regra_calculo": "Os bonus de IP e INT sobrescrevem os modificadores anteriores. Os especiais basicos (Prontidao, Vinculo, Evasao) estao ativos desde o nivel 1 e acumulam com os novos.", "niveis": {"1-2": {"ip_natural_bonus": 0, "int_bonus": 1, "especiais": ["Prontidao", "Vinculo", "Evasao", "Partilhar Magias"]}, "3-4": {"ip_natural_bonus": 0, "int_bonus": 1, "especiais": ["Prontidao", "Vinculo", "Evasao", "Partilhar Magias", "Toque"]}, "5-6": {"ip_natural_bonus": 1, "int_bonus": 2, "especiais": ["Prontidao", "Vinculo", "Evasao", "Partilhar Magias", "Toque", "Falar com o Arcano"]}, "7-8": {"ip_natural_bonus": 1, "int_bonus": 2, "especiais": ["Prontidao", "Vinculo", "Evasao", "Partilhar Magias", "Toque", "Falar com o Arcano"]}, "9-10": {"ip_natural_bonus": 2, "int_bonus": 2, "especiais": ["Prontidao", "Vinculo", "Evasao", "Partilhar Magias", "Toque", "Falar com o Arcano"]}, "11-12": {"ip_natural_bonus": 2, "int_bonus": 3, "especiais": ["Prontidao", "Vinculo", "Evasao", "Partilhar Magias", "Toque", "Falar com o Arcano", "Protecao a Magia 1d6"]}, "13-14": {"ip_natural_bonus": 3, "int_bonus": 3, "especiais": ["Prontidao", "Vinculo", "Evasao", "Partilhar Magias", "Toque", "Falar com o Arcano", "Protecao a Magia 1d6", "Espionar Familiar"]}, "15+": {"ip_natural_bonus": 3, "int_bonus": 4, "especiais": ["Prontidao", "Vinculo", "Evasao", "Partilhar Magias", "Toque", "Falar com o Arcano", "Protecao a Magia 1d6", "Espionar Familiar"]}}}, "niveis_companheiro": {"aprimoramento": "Companheiro Animal", "tipo_progressao": "incremental_por_nivel", "regra_calculo": "Pontos Totais = Base + ((Nivel_Atual - Nivel_Entrada) * Ganho_Por_Nivel). O nivel_entrada padrao eh o nivel em que o companheiro foi adquirido (geralmente 1 ou 2).", "valores_base": {"pontos_atributo": 80, "pontos_pericia": 50, "int_maxima": 2}, "ganho_por_nivel_adicional": {"pontos_atributo": 5, "pontos_pericia": 20}, "especiais": ["Ganha todos os ataques e habilidades raciais da criatura base sem custos de pontos"]}}$JSON$::jsonb,
