INSERT INTO system_rules (system_slug, rule_key, title, description, data, version)
VALUES (
    'daemon',
    'regras_jogo',
    'Guia Rápido de Regras e Sanidade',
    'Mecânicas de testes 1d100, combate, estágios de sanidade e fluxo de jogo.',
    $JSON$[{"introdução_title": "🎲 Como Jogar Daemon RPG: Guia Rápido", "introdução_subtitle": "Bem-vindo ao **FICHANATOR2000**! Se você já terminou de criar a sua ficha e quer saber como o jogo funciona na prática, este guia foi feito para você. O Sistema Daemon é simples, direto e focado na interpretação. \n\nAqui está tudo o que você precisa saber para dar seus primeiros passos!"}, {"title1": "👥 1. O Básico do RPG", "content1": "O RPG é um jogo de narrativa compartilhada.\n* **O Mestre (DM):** É quem cria a história, descreve os cenários, controla os monstros e atua como o juiz das regras.\n* **Os Jogadores:** Cada um controla um personagem (a ficha que você acabou de criar) e decide suas ações na história.\n\n**Como funciona o fluxo?** O Mestre descreve uma situação ➡️ Você diz o que seu personagem quer fazer ➡️ Os dados (ou suas habilidades) determinam se você conseguiu."}, {"title2": "🌍 2. O Universo (Daemon Medieval)", "content2": "As campanhas medievais da Daemon costumam se passar em mundos de fantasia clássica ou cenários históricos com toques sobrenaturais (como a Europa feudal misteriosa).\n* Espere encontrar cavaleiros, elfos, magos, deuses antigos e criaturas sombrias.\n* A magia existe, mas muitas vezes ela é misteriosa, poderosa e exige rituais ou intenso foco mental."}, {"title3": "🎲 3. A Regra de Ouro: Como fazer Testes?", "content3": "No Sistema Daemon, quase tudo é resolvido com um **teste de porcentagem (%)**, usando um dado de 100 lados (ou **1d100**, que na mesa real são representados por dois dados de 10 lados).\n\nSua ficha define a sua porcentagem de sucesso em cada perícia (ex: *Espada Longa 40%*, *Furtividade 35%*).\n\n1. **O Mestre pede o teste:** \"Role um teste de Procurar\".\n2. **Você joga o 1d100:**\n   * **SUCESSO:** Se o número que cair no dado for **IGUAL ou MENOR** que o valor na sua ficha.\n   * **FALHA:** Se o número for **MAIOR** que o valor na sua ficha.\n\n> 💡 **Exemplo:** Se você tem *Rastrear 50%* e o dado rola `42`, você teve sucesso! Se rolar `55`, você falhou.\n\n*Nota: O Mestre pode dar bônus ou penalidades na sua porcentagem dependendo da dificuldade da situação.*"}, {"title4": "⚔️ 4. O Combate (Passo a Passo)", "content4": "Quando o sangue corre e a iniciativa é puxada, o combate funciona em turnos:\n\n1. **Iniciativa:** Define a ordem de quem age primeiro (baseada nos seus reflexos/atributos).\n2. **Sua Vez (Ação):** No seu turno, você geralmente pode fazer **uma ação de ataque** (ou usar magia) e **um movimento**.\n3. **Atacando:** Você rola 1d100 contra a sua perícia com a arma usada (ex: *Machado 45%*). Se rolar igual ou menor, você acertou!\n4. **Defesa (A Grande Diferença):** Quem está sendo atacado tem direito a tentar se defender jogando 1d100 na perícia *Esquiva* ou *Bloqueio*. Se o defensor passar no teste dele, ele evita o seu dano!\n5. **Dano e Proteção:** Se o ataque acertar e o alvo falhar na defesa, você rola os dados de dano da arma. A Armadura do alvo absorve uma parte fixa desse dano (IP - Índice de Proteção). O que sobrar é subtraído dos **PVs (Pontos de Vida)** dele."}, {"title5": "🔮 5. Magia e Fé", "content5": "Se você joga com um feiticeiro, bruxo ou clérigo, a mágica na Daemon é maleável e dividida em:\n* **Formas e Caminhos (Focus):** Você combina elementos (Caminhos como *Fogo, Terra, Luz, Trevas*) com ações (Formas como *Criar, Controlar, Transformar*).\n* **Pontos de Magia (PMs):** Usar feitiços gasta seus PMs. Se eles zerarem, você fica exausto e não consegue conjurar mais nada até descansar.\n* **Livre e Criativa:** Muitas vezes você pode sugerir efeitos ao mestre combinando seus pontos de Focus em vez de apenas ler uma lista de magias prontas!"}, {"title6": "🧠 6. Mantendo a Sanidade", "content6": "Fique atento! Dependendo dos monstros que enfrentar ou dos traumas que sofrer, o Mestre pode pedir um **Teste de Vontade** baseado na sua **Força de Vontade (WILL)**. Falhar consecutivamente pode abalar a mente do seu herói, fazendo-o passar por estados de instabilidade mental que dão penalidades temporárias em seus atributos.\n\n### **Estágios de Sanidade**\n\n#### **Estágio 1: Saudável**\n* **Sanidade**: Mais que 100\n* **Descrição**: Mente Estável. O personagem demonstra pleno autocontrole, clareza de pensamentos e resiliência psicológica diante dos horrores e traumas do mundo. Está totalmente dentro de si e operando em seu ápice mental.\n* **Efeitos e Penalidades**: \n  * Nenhum modificador negativo. \n  * Testes de perícia e atributos operam normalmente.\n\n#### **Estágio 2: Afetado**\n* **Sanidade**: Entre 75 e 99.\n* **Descrição**: Mente Abalada. Sinais de melancolia profunda, tristeza persistente, ansiedade latente e sobressaltos começam a emergir. O foco do personagem vacila quando sob pressão ou diante de gatilhos emocionais.\n* **Efeitos e Penalidades**: \n  * Desvantagem em testes de Perícia e Atributos realizados em situações de estresse, perigo ou combate.\n\n#### **Estágio 3: Instável**\n* **Sanidade**: Entre 50 e 74\n* **Descrição**: Mente Instável. Um desconforto existencial avassalador consome o indivíduo. Pensamentos intrusivos constantes, princípios depressivos e uma visão altamente tendenciosa ou pessimista da realidade começam a nublar o raciocínio prático.\n* **Efeitos e Penalidades**: \n  * Penalidade constante de **-1 em Inteligência (INT)**.\n  * Desvantagem permanente em todos os testes de Perícia e Atributos (independentemente de estarem ou não em combate).\n\n#### **Estágio 4: Degenerado**\n* **Sanidade**: Entre 25 e 49\n* **Descrição**: Mente degenerada. Completa indiferença a si mesmo. Uma depressão profundo, ataques de pânico, paranoia e deturpação tomam sua mente. O horror toma forma em seu consciente: tudo e todos a sua volta perdem o valor e o significado\n* **Efeitos e Penalidades**: \n  * Penalidade constante de **-1 em Inteligência (INT)**.\n  * Penalidade constante de **-1 em Força de Vontade (WILL)**.\n  * Desvantagem permanente em todos os testes de Perícia e Atributos (independentemente de estarem ou não em combate).\n\n#### **Estágio 5: Louco**\n* **Sanidade**: Entre 1 e 24.\n* **Descrição**: Mente Deturpada. O limiar da loucura foi cruzado. A tristeza e a ansiedade deram lugar ao horror absoluto que agora toma a mente. O personagem ouve vozes, manifesta alucinações visuais esporádicas e é atormentado por um mix descontrolado de emoções irracionais.\n* **Efeitos e Penalidades**: \n  * Penalidade constante de **-2 em Inteligência (INT)**.\n  * Penalidade constante de **-3 em Força de Vontade (WILL)**.\n  * Penalidade constante de **-1 em Carisma (CAR)**.\n  * Desvantagem permanente em todos os testes.\n  * **Perda de Controle**: O Mestre pode assumir o controle de determinadas ações do personagem ou exigir testes para que ele execute impulsos absurdos ou irracionais.\n\n#### **Estágio 6: Suicida**\n* **Sanidade**: 0.\n* **Descrição**: Juízo Final. A mente quebrou de forma definitiva e sem retorno. O personagem perde totalmente o instinto de autopreservação, sucumbindo ao horror absoluto. Isso resulta em um ato fatal de automutilação, suicídio direto ou catatonia permanente e vegetativa.\n* **Efeitos e Penalidades**: \n  * **Morte**. O personagem se torna psicótico e eventualmente tentará se matar e não há mais salvação pra ele."}]$JSON$::jsonb,
    1
)
ON CONFLICT (system_slug, rule_key) DO UPDATE
SET title = EXCLUDED.title,
    description = EXCLUDED.description,
    data = EXCLUDED.data,
