INSERT INTO system_rules (system_slug, rule_key, title, description, data, version)
VALUES (
    'daemon',
    'regras_novo_personagem',
    'Guia de Criação de Personagem',
    'Passo a passo oficial das regras de criação de ficha Daemon.',
    $JSON${"markdown": "Bem-vindo à criação de personagens! Siga o passo a passo abaixo para estruturar sua ficha de acordo com as regras oficiais do sistema **Daemon Medieval**.\n\n---\n\n## 1. Atributos Iniciais\nVocê possui **101 pontos** para distribuir livremente entre os 8 atributos básicos do sistema. \n* **Pontuação Mínima:** 10 pontos por atributo (abaixo disso, você possui uma deficiência correlacionada a esse ATRIBUTO).\n* **Pontuação Máxima:** 18 pontos por atributo (para humanos normais).\n\n**Os Atributos são:**\n* **Constituição (CON):** Resistência física e saúde.\n* **Força (FR):** Poder muscular e dano físico.\n* **Destreza (DEX):** Agilidade, reflexos e precisão.\n* **Agilidade (AGI):** Velocidade de deslocamento e iniciativa.\n* **Inteligência (INT):** Raciocínio, memória e aprendizado.\n* **Força de Vontade (WILL):** Determinação e resistência mental.\n* **Percepção (PER):** Prontidão dos sentidos.\n* **Carisma (CAR):** Magnetismo pessoal e persuasão.\n\n---\n\n## 2. Pontos de Aprimoramento\nOs aprimoramentos representam qualidades, vantagens ou defeitos únicos do seu personagem.\n\n* **Pontos Iniciais:** Você começa com **5 pontos** de Aprimoramento.\n* **Uso dos Pontos:** Podem ser gastos para comprar **Aprimoramentos Positivos**.\n* **Defeitos (Aprimoramentos Negativos):** Você pode adquirir **Aprimoramentos Negativos** (desvantagens) para recuperar pontos. \n  * *Regra Limite:* Você pode receber no máximo **3 pontos extras** vindos de Aprimoramentos Negativos (totalizando o teto máximo de 8 pontos para gastar).\n\n---\n\n## 3. Perícias e Habilidades\nAs perícias medem o conhecimento prático e técnico do seu personagem em porcentagem (%).\n\n* **Perícias Mundanas:** Você recebe **pontos iniciais** baseados na sua classe/kit para distribuir em perícias comuns (como Espadas, Furtividade, Cavalgar, etc.).\n* **Perícias Místicas:** Caso seu personagem seja um conjurador de magia ou possua aptidão mística, pontos específicos de perícias místicas serão disponibilizados.\n* **Custo de Evolução:** No nível 1, os pontos são distribuídos diretamente de forma a customizar o conhecimento do seu personagem para enfrentar os primeiros desafios.\n\n---\n\n## 4. Pontos de Vida (PV) e Energia\n* **Pontos de Vida (PV):** Calculados somando a sua **Constituição (CON)** + **Força (FR)** dividido por 2, mais os bônus específicos de nível.\n* **Pontos de Mana (PM) / Focus:** Se aplicável à sua classe mística para a conjuração de magias e rituais.\n\n---\n\n### 💡 Dica de Validação\n*Certifique-se de gastar exatamente os 101 pontos de atributos e validar o saldo de aprimoramentos (Máximo de 5 pontos base + até 3 pontos de desvantagens) antes de avançar para a finalização da sua ficha.*"}$JSON$::jsonb,
    1
)
ON CONFLICT (system_slug, rule_key) DO UPDATE
SET title = EXCLUDED.title,
    description = EXCLUDED.description,
    data = EXCLUDED.data,
    updated_at = CURRENT_TIMESTAMP;
